  INSERT INTO lesson_revisions (topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES (v_topic_revision_id,v_lesson_id,v_teacher_id,'Present Be: Statements and Questions','Use am, is, and are in short everyday statements, negatives, and questions.','Use am with I, is with he, she, and it, and are with you, we, and they. Add not for a negative: She is not late. Put be before the subject in a question: Are they ready? Contractions include I''m, isn''t, and aren''t.','GRAMMAR',1,10,FALSE) RETURNING id INTO v_lesson_revision_id;
