  INSERT INTO topic_revisions (revision_id,source_topic_id,name,description,order_index) VALUES (v_revision_id,v_topic_id,'Dialogue Patterns: Who Is Speaking?','Notice pronouns in short conversations at home, school, and work.',1) RETURNING id INTO v_topic_revision_id;
  INSERT INTO lesson_revisions (topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES (v_topic_revision_id,v_lesson_id,v_teacher_id,'Meet the People: Pronouns in Conversation','Follow short exchanges and replace names with the correct subject pronoun.','Notice the speaker in each exchange. When Linh says, ''I am a student,'' I means Linh. When Nam answers, ''You are my friend,'' you means the listener. For two people together use we; for a group use they. Example: ''Where are the bags?'' ''They are here.''','GRAMMAR',1,10,FALSE) RETURNING id INTO v_lesson_revision_id;
  INSERT INTO question_revisions (lesson_revision_id,source_question_id,teacher_id,type,question_text,explanation,correct_answer,knowledge_point,order_index,difficulty,xp_reward) VALUES (v_lesson_revision_id,v_question_id,v_teacher_id,'MULTIPLE_CHOICE','Linh says, “___ am a student.”','The speaker uses I to talk about herself.','I','pronouns in dialogue',1,'easy',10) RETURNING id INTO v_question_revision_id;
