  INSERT INTO topic_revisions (revision_id,source_topic_id,name,description,order_index) VALUES (v_revision_id,v_topic_id,'Dialogue Patterns: Be in Real Exchanges','Notice am, is, and are while people ask and answer simple questions.',2) RETURNING id INTO v_topic_revision_id;
  INSERT INTO lesson_revisions (topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES (v_topic_revision_id,v_lesson_id,v_teacher_id,'At the Café: Be in Short Exchanges','Use affirmative, negative, and question forms of be in friendly café conversations.','Listen for the subject before be. ''I am hungry'' uses am; ''The coffee is hot'' uses is; ''We are early'' uses are. In a question, be comes first: ''Are you ready?'' In a negative reply, use not: ''No, I am not.''','GRAMMAR',1,10,FALSE) RETURNING id INTO v_lesson_revision_id;
